// refactored from https://www.shadertoy.com/view/Ms2SDc

const float PI = 3.14159;
const float ep = 0.02;
const vec3 up = vec3(0.0, 1.0, 0.0);

const vec3 lightColor = vec3(0.08, 0.02, -0.01);
const float atmosphere = 0.0625;
const int maxIterations = 96;
const float holeWidth = 0.05;

// takes a 2d vector and rotates it by some angle
vec2 rotate(vec2 vector, float angle) {
    float cosAngle = cos(angle);
    float sinAngle = sin(angle);
    return vec2(
        cosAngle * vector.x - sinAngle * vector.y,
        sinAngle * vector.x + cosAngle * vector.y    
    );
}

// takes a point in space and returns how far it is from the scene
// this is a very compact way to represent a scene mathematically
float sceneSDF(vec3 pos) {
	float ground = dot(pos, up) + 0.75;
	float structure = length(abs(mod(pos, 2.0) - 1.0)) - 1.35 
        + 0.05 * cos(PI * pos.x * 4.0) 
        + 0.05 * sin(PI * pos.z * 4.0);
	float slice1 = length(max(abs(mod(pos, 2.0) - 1.0).xz - 1.0, 0.5)) - 0.075 
        + 0.1 * cos(pos.y * 36.0);
	float slice2 = length(abs(mod(pos, 0.5)) - 0.25) - 0.975;

	float bubble_w = 0.8 + 0.2 * cos(PI * pos.z) + 0.2 * cos(PI * pos.x);
	float bubble = length(mod(pos, 0.125) - 0.0625) - bubble_w;

	float hole = length(abs(mod(pos.xz, 1.0) - 0.5)) - holeWidth;

	return max(
        slice1 + slice2,
        min(
            -structure, 
            max(
                -hole - slice2 * 0.375,
                ground + bubble
            )
        )
    );
}

// starts from the camera location and moves in the rayDirection until it touches the scene
// uses the point where the ray hits the scene and its distance from the camera to calculate a color
vec3 calculateRayColor(vec3 cameraLocation, vec3 rayDirection) {
    float rayLength = 0.0;
    for (int i = 0; i < maxIterations; i++) {
        float distance = sceneSDF(cameraLocation + rayDirection * rayLength);
        if (abs(distance) < 0.005) break;
        rayLength += distance * 0.5;
    }

    vec3 hitPoint = cameraLocation + rayDirection * rayLength;

    float lightIntensity = dot(
        normalize(vec3(
            sceneSDF(hitPoint + vec3(-ep, ep, ep)), 
            sceneSDF(hitPoint + vec3(ep, -ep, -ep)), 
            sceneSDF(hitPoint + vec3(ep, ep, -ep))
        )), 
        vec3(0.1)
    );

    vec3 baseColor = vec3(lightIntensity) - rayLength * atmosphere;
    return baseColor * baseColor + vec3(lightIntensity) + rayLength * lightColor;
}

// returns the direction of the ray for a screen coordinate
vec3 getRayDirection(vec2 fragCoord) {
    vec3 rayDirection = normalize(
        vec3((2.0 * fragCoord / iResolution.xy - 1.0) * vec2(1.625, 1.0), 0.75)
    );
    rayDirection.yz = rotate(rayDirection.yz, PI * 0.25 * sin(PI * iTime * 0.125));
    rayDirection.zx = rotate(rayDirection.zx, PI * cos(-PI * iTime * 0.05));
    rayDirection.xy = rotate(rayDirection.xy, PI * 0.125 * cos(PI * iTime * 0.125));
    return rayDirection;
}

void mainImage(out vec4 fragColor, vec2 fragCoord) {
    vec3 cameraLocation = vec3(
        1.5 * cos(PI * iTime * 0.125), 
        4.0 - 3.0 * sin(PI * iTime * 0.125), 
        -1.0 - iTime
    );

    fragColor = vec4(
        calculateRayColor(cameraLocation, getRayDirection(fragCoord)), 
        1.0
    );
}
